const std = @import("std"); const pars = @import("pa-carz-pars.zig");
fn arenNewz() std.heap.ArenaAllocator { return std.heap.ArenaAllocator.init(std.testing.allocator); }
const BONB =
    \\<html><head><title>Bán xe ô tô Toyota Land Cruiser VX.R 3.5 V6 HEV 2026 giá 4 Tỷ 730 Triệu | 6986108</title></head><body>
    \\<div class="menu"><a>Giá xe ô tô</a><a>Dưới 500 triệu</a></div>
    \\<div class="title"><h1>Xe Toyota Land Cruiser VX.R 3.5 V6 HEV 2026</h1><span>- 4 Tỷ 730 Triệu</span></div>
    \\<div>Thông số kỹ thuật</div>
    \\<div><label>Năm sản xuất:</label><span>2026</span></div><div><label>Tình trạng:</label><span>Xe mới</span></div>
    \\<div><label>Xuất xứ:</label><span>Nhập khẩu</span></div><div><label>Kiểu dáng:</label><span>SUV</span></div>
    \\<div><label>Hộp số:</label><span>Số tự động</span></div><div><label>Động cơ:</label><span>Hybrid 3.4 L</span></div>
    \\<div><label>Màu ngoại thất:</label><span>Trắng</span></div><div><label>Số chỗ ngồi:</label><span>7 chỗ</span></div>
    \\<div><label>Dẫn động:</label><span>AWD - 4 bánh toàn thời gian</span></div>
    \\<div>Thông tin mô tả</div><div>Bán Toyota Landcruiser HEV mới 100% giao ngay.</div><div>Liên hệ người bán</div><div>Lê Văn Thuỳ</div>
    \\<div><label>Điện thoại:</label></div><div>0922 079 ***</div><div>Địa chỉ: 368 Võ Chí Công - Tây Hồ - Hà Nội</div>
    \\</body></html>
;
test "bonbanh-shaped page: spec labels, price-only line beats menu, seller name dropped" { var aren = arenNewz(); defer aren.deinit(); const carz = try pars.carzPars(aren.allocator(), "https://bonbanh.com/xe-toyota-land_cruiser-vx.r-3.5-v6-hev-2026-6986108", BONB, 2026); try std.testing.expectEqualStrings("bonbanh.com", carz.site); try std.testing.expectEqualStrings("6986108", carz.lidz); try std.testing.expectEqualStrings("Toyota", carz.make); try std.testing.expectEqualStrings("Land Cruiser", carz.modl); try std.testing.expectEqualStrings("VX.R 3.5 V6 HEV", carz.trim); try std.testing.expectEqual(@as(i64, 2026), carz.year); try std.testing.expectEqual(@as(i64, 4_730_000_000), carz.pric); try std.testing.expectEqualStrings("new", carz.cond); try std.testing.expectEqualStrings("HEV", carz.powr); try std.testing.expectEqualStrings("AT", carz.gear); try std.testing.expectEqual(@as(i64, 7), carz.seat); try std.testing.expectEqual(@as(i64, -1), carz.kmzz); try std.testing.expectEqualStrings("Hà Nội", carz.prov); try std.testing.expectEqualStrings("private", carz.sell); try std.testing.expectEqualStrings("", carz.shop); try std.testing.expect(std.mem.indexOf(u8, carz.phon, "0922") != null); try std.testing.expect(std.mem.indexOf(u8, carz.text, "Lê Văn") == null); }
const CHOT =
    \\<html><head><title>Toyota Fortuner 2017 Số sàn Bạc 84.281 km - 134891221</title><script type="application/ld+json">{"@context":"https://schema.org","@type":["Product","Car"],"name":"Toyota Fortuner","offers":{"@type":"Offer","price":"520000000","priceCurrency":"VND"}}</script></head><body>
    \\<div>Toyota Fortuner 2017</div><div>520.000.000 đ (Trả góp từ 5.43 triệu /tháng)</div><div>Xã Trừ Văn Thố, Huyện Bàu Bàng, Bình Dương</div>
    \\<div>Mô tả chi tiết</div><div>Bán xe Fortuner số sàn máy dầu. Zalo 0966.353.678</div><div>Thông số chi tiết</div>
    \\<div>Số Km đã đi</div><div>84.281</div><div>Số đời chủ</div><div>1 chủ</div><div>Còn hạn đăng kiểm</div><div>Có</div><div>Xuất xứ</div><div>Đang cập nhật</div><div>Tình trạng</div><div>Đã sử dụng</div>
    \\<div>Hãng</div><div>Toyota</div><div>Dòng xe</div><div>Fortuner</div><div>Năm sản xuất</div><div>2017</div><div>Hộp số</div><div>Số sàn</div><div>Nhiên liệu</div><div>Dầu</div><div>Số chỗ</div><div>7</div><div>Trọng tải</div><div>&gt; 2 tấn</div>
    \\<div>Xe tương tự</div><div>Hộp số</div><div>Số tự động</div><div>Nhiên liệu</div><div>Xăng</div>
    \\</body></html>
;
test "chotot-shaped page: JSON-LD price, labels without colon, junk value skipped, similar-cars section ignored" { var aren = arenNewz(); defer aren.deinit(); const carz = try pars.carzPars(aren.allocator(), "https://xe.chotot.com/mua-ban-oto-huyen-bau-bang-binh-duong/134891221.htm", CHOT, 2026); try std.testing.expectEqualStrings("134891221", carz.lidz); try std.testing.expectEqual(@as(i64, 520_000_000), carz.pric); try std.testing.expectEqual(@as(i64, 84281), carz.kmzz); try std.testing.expectEqual(@as(i64, 1), carz.owns); try std.testing.expectEqualStrings("used", carz.cond); try std.testing.expectEqualStrings("", carz.orig); try std.testing.expectEqualStrings("MT", carz.gear); try std.testing.expectEqualStrings("DSL", carz.powr); try std.testing.expectEqualStrings("Dầu", carz.fuel); try std.testing.expectEqualStrings("Bình Dương", carz.prov); try std.testing.expectEqualStrings("0966353678", carz.phon); try std.testing.expect(std.mem.indexOf(u8, carz.xtra, "Còn hạn đăng kiểm") != null); try std.testing.expect(std.mem.indexOf(u8, carz.xtra, "> 2 tấn") != null); }
test "nbsp in the price line, km from the title, email phone rejected" { var aren = arenNewz(); defer aren.deinit(); const html = "<title>Ford Ranger 2023 - 60,000km</title><div>1.030.000.000\xC2\xA0đ (Trả góp từ 11,5 triệu/tháng)</div><div>Nhiên liệu</div><div>Dầu</div><div>Hộp số</div><div>Số tự động</div><div>Điện thoại: 0853603616; Email: x@y.vn</div>"; const carz = try pars.carzPars(aren.allocator(), "https://carpla.vn/xe/ford-ranger-2023-f8xz1", html, 2026); try std.testing.expectEqual(@as(i64, 1_030_000_000), carz.pric); try std.testing.expectEqual(@as(i64, 60000), carz.kmzz); try std.testing.expectEqualStrings("Ford", carz.make); try std.testing.expectEqualStrings("used", carz.cond); try std.testing.expectEqualStrings("Ranger", carz.modl); try std.testing.expectEqual(@as(i64, 2023), carz.year); try std.testing.expectEqualStrings("", carz.phon); }
test "title price uses the part after giá and ignores the listing id after the dash, placeholder trim dropped" { var aren = arenNewz(); defer aren.deinit(); const html = "<title>Mua bán Porsche Panamera Phiên bản khác 2020 giá 3 tỉ 250 triệu - 23447006</title><div>Phiên bản:</div><div>Phiên bản khác</div><div>Km đã đi:</div><div>7.000 km</div>"; const carz = try pars.carzPars(aren.allocator(), "https://oto.com.vn/mua-ban-xe-porsche-panamera-ha-noi/ho-tro-vay-toi-da-aidxc23447006", html, 2026); try std.testing.expectEqual(@as(i64, 3_250_000_000), carz.pric); try std.testing.expectEqualStrings("Porsche", carz.make); try std.testing.expectEqualStrings("Panamera", carz.modl); try std.testing.expectEqualStrings("", carz.trim); try std.testing.expectEqual(@as(i64, 7000), carz.kmzz); try std.testing.expectEqualStrings("aidxc23447006", carz.lidz); }
test "new is only believed for a recent model year, trim stops at the year and colon" { var aren = arenNewz(); defer aren.deinit(); const oldz = try pars.carzPars(aren.allocator(), "https://carmudi.vn/ban-xe-oto-bmw-x3-543842/", "<title>BMW X3 xDrive20i 2020: Giá bán &amp; khuyến mãi mới 11/2026</title><div>Số KM</div><div>Xe mới</div><div>960 triệu</div>", 2026); try std.testing.expectEqualStrings("", oldz.cond); try std.testing.expectEqualStrings("xDrive20i", oldz.trim); try std.testing.expectEqual(@as(i64, 960_000_000), oldz.pric); const rece = try pars.carzPars(aren.allocator(), "https://carmudi.vn/ban-xe-oto-vinfast-vf8-1/", "<title>VinFast VF8 2026</title><div>Số KM</div><div>Xe mới</div>", 2026); try std.testing.expectEqualStrings("new", rece.cond); try std.testing.expectEqualStrings("VinFast", rece.make); }
test "class: pickup, truck, plain car; sold notice sets the gone hint; individual names never stored" { var aren = arenNewz(); defer aren.deinit(); const aloz = aren.allocator(); try std.testing.expectEqualStrings("pickup", (try pars.carzPars(aloz, "https://x.vn/a-1", "<title>Ford Ranger bán tải 2020</title>", 2026)).clsz); try std.testing.expectEqualStrings("truck", (try pars.carzPars(aloz, "https://x.vn/a-2", "<title>Xe tải Isuzu 2.5 tấn thùng kín 2019</title>", 2026)).clsz); try std.testing.expectEqualStrings("car", (try pars.carzPars(aloz, "https://x.vn/a-3", "<title>Mazda 3 2021</title>", 2026)).clsz); try std.testing.expect((try pars.carzPars(aloz, "https://x.vn/a-4", "<div>Tin đã bán</div><div>Mazda 3</div>", 2026)).gone); const dler = try pars.carzPars(aloz, "https://carmudi.vn/a-5", "<div>Đăng bởi</div><div>Showroom Ô tô Minh Phát</div>", 2026); try std.testing.expectEqualStrings("dealer", dler.sell); try std.testing.expectEqualStrings("Showroom Ô tô Minh Phát", dler.shop); const priv = try pars.carzPars(aloz, "https://carmudi.vn/a-6", "<div>Đăng bởi</div><div>Trung Sơn</div>", 2026); try std.testing.expectEqualStrings("private", priv.sell); try std.testing.expectEqualStrings("", priv.shop); }
test "url helpers and empty or broken html never crash" { try std.testing.expectEqualStrings("tinbanxe.vn", pars.hostOfzz("https://www.tinbanxe.vn/audi-q8-trang-89570/?x=1")); try std.testing.expectEqualStrings("89570", pars.lidzOfzz("https://tinbanxe.vn/audi-q8-2022-trang-89570/")); try std.testing.expectEqualStrings("134891221", pars.lidzOfzz("https://xe.chotot.com/a-b/134891221.htm?x=1")); var aren = arenNewz(); defer aren.deinit(); for ([_][]const u8{ "", "<", "<div", "\x00\xff", "<script>" }) |badz| _ = try pars.carzPars(aren.allocator(), "https://a.vn/x", badz, 2026); }
test "detail urls of the newer car sites, listing and category pages stay out" { const help = @import("pa-carz-help.zig"); const goods = [_][]const u8{ "https://muaban.net/o-to/ban-xe-quan-12/ban-xe-id71052558", "https://oto360.net/xe-oto-cu/17897051193755.html", "https://vucar.vn/phien-dau-gia/tin-xe/kia-cerato-1-6at-2018", "https://vuabantai.net/Xe-ford-ranger-112488", "https://fordassured.com.vn/ford-ranger-xls-2015", "https://xetaitoanquoc.com/ban-xe-tai-kia-k135-2015", "https://xedaukeocu.com/san-pham/mooc-bon.html" }; for (goods) |urlz| try std.testing.expect(help.detaUrlz(urlz)); const bads = [_][]const u8{ "https://muaban.net/o-to/ban-o-to-xe-tai-dau-keo", "https://oto360.net/xe-oto-cu", "https://vucar.vn/phien-dau-gia/tin-xe", "https://vuabantai.net/", "https://fordassured.com.vn/ford-ranger-cu", "https://xetaitoanquoc.com/", "https://xedaukeocu.com/san-pham/page/2" }; for (bads) |urlz| try std.testing.expect(!help.detaUrlz(urlz)); }
test "a phone line is not a price, category text is not a make, body words are not a model, truck dealers sell trucks" { var aren = arenNewz(); defer aren.deinit(); const aloz = aren.allocator(); const phon = try pars.carzPars(aloz, "https://fordassured.com.vn/ford-ranger-x", "<title>Ford Ranger XLS 2015</title><div>0931 248 248</div>", 2026); try std.testing.expectEqual(@as(i64, 0), phon.pric); const cate = try pars.carzPars(aloz, "https://muaban.net/o-to/a/b-id1", "<title>Xe Hino FC, đời 2017</title><div>Hãng</div><div>Xe tải, đầu kéo</div>", 2026); try std.testing.expectEqualStrings("Hino", cate.make); try std.testing.expectEqualStrings("FC", cate.modl); const body = try pars.carzPars(aloz, "https://vuabantai.net/Xe-x", "<title>Ford Ranger 2019</title><div>Dòng xe</div><div>Truck</div>", 2026); try std.testing.expectEqualStrings("Ranger", body.modl); const trai = try pars.carzPars(aloz, "https://xedaukeocu.com/san-pham/a.html", "<title>MOOC SOOSAN 2021</title>", 2026); try std.testing.expectEqualStrings("truck", trai.clsz); const help = @import("pa-carz-help.zig"); try std.testing.expectEqualStrings("", help.modlClea("ĐỜI 2014")); try std.testing.expectEqualStrings("", help.modlClea(",")); try std.testing.expectEqualStrings("FC", help.modlClea("FC,")); }
